__global__ void square_matrix_mul_kernel_tiled(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Global memory coordinates of the current thread
    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    float sum = 0.0f;

    // Iterate over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load tiles into shared memory
        int A_shared_row_idx = t * TILE_SIZE + threadIdx.y;
        int B_shared_col_idx = t * TILE_SIZE + threadIdx.x;

        if (row < N && A_shared_col_idx < N) {
            As[threadIdx.y][threadIdx.x] = A[row * N + A_shared_col_idx];
        } else {
            As[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }

        if (B_shared_row_idx < N && col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[B_shared_row_idx * N + col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = 0.0f; // Pad with zeros if out of bounds
        }
        __syncthreads();

        // Perform matrix multiplication on shared memory tiles
        for (int k = 0; k < TILE_SIZE; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }
        __syncthreads();
    }

    // Write result to global memory
